<?php
if(!defined('ABSPATH')){exit;} final class DSVS_Parser { private static function xpath($html){if(!class_exists('DOMDocument')){return false;}$doc=new DOMDocument();$old=libxml_use_internal_errors(true);$ok=$doc->loadHTML('<?xml encoding="UTF-8">'.$html);libxml_clear_errors();libxml_use_internal_errors($old);return $ok?new DOMXPath($doc):false;} private static function clean($text){return trim(preg_replace('/\s+/u',' ',$text));} private static function cells($xpath,$row){$cells=array();foreach($xpath->query('./th|./td',$row) as $cell){$value=self::clean($cell->textContent);if(''!==$value){$cells[]=$value;}}return $cells;} public static function get_standings($html){$xpath=self::xpath($html);if(!$xpath){return array();}foreach($xpath->query('//table') as $table){$text=self::clean($table->textContent);if(false===stripos($text,'Mannschaft')||false===stripos($text,'Partien')){continue;}$rows=array();foreach($xpath->query('.//tr',$table) as $row){$cells=self::cells($xpath,$row);if(count($cells)>=9&&ctype_digit($cells[0])){$rows[]=array_slice($cells,0,9);}}if($rows){return $rows;}}return array();} public static function get_current_games($html){return self::games($html,true);} public static function get_schedule($html){$games=self::games($html,false);usort($games,function($a,$b){return $a['timestamp']<=>$b['timestamp'];});return $games;} private static function games($html,$current_only){$xpath=self::xpath($html);if(!$xpath){return array();}$games=array();foreach($xpath->query('//table') as $table){$is_current=false!==stripos($table->textContent,'AKTUELLE ERGEBNISSE');if($current_only!==$is_current){continue;}foreach($xpath->query('.//tr',$table) as $row){$game=self::parse_game(self::cells($xpath,$row));if($game){$games[]=$game;}}}return $games;} private static function parse_game($cells){$date_index=false;foreach($cells as $index=>$cell){if(preg_match('/(\d{2}\.\d{2}\.\d{4}).*?(\d{2}:\d{2})/u',$cell,$match)){$date_index=$index;$date=$match[1];$time=$match[2];break;}}if(false===$date_index){return false;}$rest=array_slice($cells,$date_index+1);foreach($rest as $index=>$value){if(preg_match('/^(?:\d+\s*:\s*\d+|:)$/',$value)&&$index>=1&&isset($rest[$index+1])){$dt=DateTime::createFromFormat('!d.m.Y H:i',$date.' '.$time,wp_timezone());if(!$dt){return false;}return array('date'=>$date,'time'=>$time,'timestamp'=>$dt->getTimestamp(),'home'=>$rest[$index-1],'result'=>preg_replace('/\s+/','',$value),'away'=>$rest[$index+1]);}}return false;} public static function get_ranking($html){$xpath=self::xpath($html);if(!$xpath){return array();}foreach($xpath->query('//table') as $table){$table_text=self::clean($table->textContent);if(false===stripos($table_text,'Rangliste')||false===stripos($table_text,'Begegnungen')||false===stripos($table_text,'Quote')){continue;}$ranking=array();foreach($xpath->query('.//tr',$table) as $row){$cells=array();foreach($xpath->query('./td',$row) as $cell){$cells[]=$cell;}if(7!==count($cells)){continue;}$rank=self::clean($cells[0]->textContent);$played=self::clean($cells[3]->textContent);$won=self::clean($cells[4]->textContent);$lost=self::clean($cells[5]->textContent);$quote=self::clean($cells[6]->textContent);if(!preg_match('/^\d+$/',$rank)||!preg_match('/^\d+$/',$played)||!preg_match('/^\d+$/',$won)||!preg_match('/^\d+$/',$lost)||false===strpos($quote,'%')){continue;}$identity=self::parse_ranking_identity($xpath,$cells[2]);$ranking[]=array('rank'=>$rank,'player'=>$identity['player'],'team'=>$identity['team'],'played'=>$played,'won'=>$won,'lost'=>$lost,'quote'=>$quote);}if($ranking){return $ranking;}}return array();} private static function parse_ranking_identity($xpath,$cell){$player_link=$xpath->query('.//a[contains(@href,"verein-mitglied-statistiken.php")][1]',$cell)->item(0);$player=$player_link?self::clean($player_link->textContent):'';$team='';$seen_break=false;foreach($cell->childNodes as $node){if(XML_ELEMENT_NODE===$node->nodeType&&'br'===strtolower($node->nodeName)){$seen_break=true;continue;}if($seen_break&&XML_TEXT_NODE===$node->nodeType){$candidate=self::clean($node->textContent);if(''!==$candidate){$team=$candidate;break;}}}if(''===$team){$full=self::clean($cell->textContent);if(''!==$player&&0===mb_stripos($full,$player)){$team=trim(mb_substr($full,mb_strlen($player)));}}return array('player'=>$player,'team'=>$team);} public static function filter_ranking($ranking,$limit=20,$include_own=true){if(0===$limit){return $ranking;}$visible=array_slice($ranking,0,$limit);if(!$include_own){return $visible;}$included_ranks=array();foreach($visible as $entry){$included_ranks[(string)$entry['rank']]=true;}foreach($ranking as $entry){if(DSVS_Settings::is_highlighted_team($entry['team'])&&!isset($included_ranks[(string)$entry['rank']])){$visible[]=$entry;$included_ranks[(string)$entry['rank']]=true;}}usort($visible,function($a,$b){return (int)$a['rank']<=>(int)$b['rank'];});return $visible;} public static function get_upcoming_highlighted_games($games,$limit){$now=current_time('timestamp');$games=array_values(array_filter($games,function($game)use($now){return $game['timestamp']>=$now&&':'===$game['result']&&(DSVS_Settings::is_highlighted_team($game['home'])||DSVS_Settings::is_highlighted_team($game['away']));}));return array_slice($games,0,$limit);} }
